import struct
import sys

import numpy as np  # noqa: F401  (not required; wgpu may pull it in)
import wgpu

WG = 256

GEN_SHADER = """
struct Params { count: u32, seed: u32, bins: u32, pad: u32 };
@group(0) @binding(0) var<uniform> params: Params;
@group(0) @binding(1) var<storage, read_write> values: array<u32>;

@compute @workgroup_size(256)
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
    let i = gid.x;
    if (i >= params.count) { return; }
    let a = ((i % 40000u) * 1597u + params.seed + 51749u) % 40000u;
    let b = (a * a + a * 37u + 11u) % 40009u;
    let c = (b * 613u + 7919u) % 40009u;
    let d = (c + (i / 40000u) * 7919u) % 40009u;
    values[i] = d % 1000u;
}
"""

COUNT_SHADER = """
struct Params { count: u32, seed: u32, bins: u32, pad: u32 };
@group(0) @binding(0) var<uniform> params: Params;
@group(0) @binding(1) var<storage, read> values: array<u32>;
@group(0) @binding(2) var<storage, read_write> hist: array<atomic<u32>>;

var<workgroup> local_hist: array<atomic<u32>, 256>;

@compute @workgroup_size(256)
fn main(@builtin(global_invocation_id) gid: vec3<u32>,
        @builtin(local_invocation_id) lid: vec3<u32>) {
    atomicStore(&local_hist[lid.x], 0u);
    workgroupBarrier();
    let i = gid.x;
    if (i < params.count) {
        let bin = values[i] * params.bins / 1000u;
        atomicAdd(&local_hist[bin], 1u);
    }
    workgroupBarrier();
    if (lid.x < params.bins) {
        let n = atomicLoad(&local_hist[lid.x]);
        if (n > 0u) { atomicAdd(&hist[lid.x], n); }
    }
}
"""


def main():
    with open(sys.argv[1]) as f:
        count, seed, bins = (int(x) for x in f.read().split()[:3])

    adapter = wgpu.gpu.request_adapter_sync(power_preference="high-performance")
    device = adapter.request_device_sync()

    S = wgpu.BufferUsage
    params = device.create_buffer_with_data(
        data=struct.pack("<4I", count, seed, bins, 0),
        usage=S.UNIFORM,
    )
    values = device.create_buffer(size=max(count, 1) * 4, usage=S.STORAGE)
    hist = device.create_buffer(
        size=256 * 4, usage=S.STORAGE | S.COPY_DST | S.COPY_SRC
    )
    device.queue.write_buffer(hist, 0, bytes(256 * 4))

    gen = device.create_compute_pipeline(
        layout="auto",
        compute={
            "module": device.create_shader_module(code=GEN_SHADER),
            "entry_point": "main",
        },
    )
    cnt = device.create_compute_pipeline(
        layout="auto",
        compute={
            "module": device.create_shader_module(code=COUNT_SHADER),
            "entry_point": "main",
        },
    )
    gen_bg = device.create_bind_group(
        layout=gen.get_bind_group_layout(0),
        entries=[
            {"binding": 0, "resource": {"buffer": params}},
            {"binding": 1, "resource": {"buffer": values}},
        ],
    )
    cnt_bg = device.create_bind_group(
        layout=cnt.get_bind_group_layout(0),
        entries=[
            {"binding": 0, "resource": {"buffer": params}},
            {"binding": 1, "resource": {"buffer": values}},
            {"binding": 2, "resource": {"buffer": hist}},
        ],
    )

    groups = (count + WG - 1) // WG
    if groups > 0:
        enc = device.create_command_encoder()
        p = enc.begin_compute_pass()
        p.set_pipeline(gen)
        p.set_bind_group(0, gen_bg)
        p.dispatch_workgroups(groups)
        p.set_pipeline(cnt)
        p.set_bind_group(0, cnt_bg)
        p.dispatch_workgroups(groups)
        p.end()
        device.queue.submit([enc.finish()])

    data = device.queue.read_buffer(hist)
    counts = struct.unpack("<256I", bytes(data))
    out = [f"BIN {i} {counts[i]}" for i in range(bins)]
    out.append(f"TOTAL {count}")
    sys.stdout.write("\n".join(out) + "\n")


if __name__ == "__main__":
    main()
